"""Central settings for the planner. Change things here, not in the code."""
from pathlib import Path

PLANNER_DIR = Path(__file__).resolve().parent
ROOT = PLANNER_DIR.parent

# Real inputs (used automatically when present)
REAL_GTFS_DIR = ROOT / "data" / "raw" / "gtfs"
REAL_CROWDING = ROOT / "outputs" / "crowding.csv"
REAL_ROUTE_HOUR = ROOT / "outputs" / "crowding_route_hour.csv"   # fallback when a stretch row is missing
REAL_STOP_ORDER = ROOT / "outputs" / "stop_order.csv"            # stop order rebuilt from tickets

# Demo inputs (generated by make_fake_data.py)
SAMPLE_DIR = PLANNER_DIR / "sample_data"
SAMPLE_GTFS_DIR = SAMPLE_DIR / "gtfs"
SAMPLE_CROWDING = SAMPLE_DIR / "crowding.csv"

CACHE_DIR = PLANNER_DIR / ".cache"

# GTFS direction_id -> UP/DOWN used in crowding.csv.
# Only used when the GTFS route name has no UP/DOWN suffix.
DIRECTION_MAP = {0: "UP", 1: "DOWN"}

# How crowding.csv numbers its stops:
#   "gtfs"     -> stop_seq_from/to are GTFS stop_sequence values
#   "position" -> stop_seq_from/to are 1-based positions along the route
STOP_SEQ_MODE = "gtfs"

# Planner limits
WALK_SPEED_MPS = 1.2
MAX_TRANSFER_WALK_M = 400
MIN_TRANSFER_BUFFER_S = 120
MAX_WAIT_S = 90 * 60
HOUR_FALLBACK = 0            # 0 = never borrow another hour's data (a missing row means 'no data'); n = look +/- n hours
MAX_CANDIDATES = 15          # journeys scored for crowding before ranking
MAX_SHOWN = 5
MAX_TRANSFER_SHOWN = 2
TRANSFER_SLOWER_LIMIT = 1.3  # show a transfer option only if total time <= 1.3 x best direct

# Ticket-only mode (no GTFS yet): there is no timetable, so ride time is a rough estimate.
TICKET_MODE_SEC_PER_STOP = 150     # about 2.5 minutes per stop (assumption, flagged in the app)
TICKET_MODE_TRANSFER_WAIT_S = 300  # assumed wait when changing buses (assumption)

LEVEL_SCORE = {"seats": 0.0, "standing": 1.0, "crowded": 2.0}
LEVEL_LABEL = {
    "seats": "Seats likely",
    "standing": "Standing room likely",
    "crowded": "Likely crowded",
    "unknown": "Not enough data",
}
LEVEL_COLOUR = {
    "seats": "#2e9e4f",
    "standing": "#e0a000",
    "crowded": "#d6362f",
    "unknown": "#8a8f98",
}
LEVEL_ICON = {"seats": "🟢", "standing": "🟡", "crowded": "🔴", "unknown": "⚪"}
